import sys
import os
import json
import re

def format_date(s: str):
    """Convert a date string to YYYY-MM-DD if possible, else None."""
    s = s.strip()
    if not s:
        return None
    if re.fullmatch(r'\d{8}', s):
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
        return s
    return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)
    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    # Mapping from rule_id to fact name to field name, based on the decision rules.
    fact_field = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date",
        },
        "fda.terminated_180d": {
            "initiation date": "recall_initiation_date",
            "termination date": "termination_date",
        },
    }

    # Locate the document file. The decision rules name the document "fda_enforcement_reports".
    document = "fda_enforcement_reports"
    file_path = os.path.join(packet_dir, document + ".json")
    if not os.path.exists(file_path):
        for fname in os.listdir(packet_dir):
            stem, _ = os.path.splitext(fname)
            if stem == document:
                file_path = os.path.join(packet_dir, fname)
                break
    document = os.path.splitext(os.path.basename(file_path))[0]

    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    records = data.get("results", [])

    # Index records by recall_number (the entity in the manifest pairs).
    index = {}
    for rec in records:
        rn = rec.get("recall_number")
        if rn:
            index.setdefault(rn, []).append(rec)

    output = {}
    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        result = {}
        for fact_name in fact_names:
            field = fact_field.get(rule_id, {}).get(fact_name)
            if not field:
                result[fact_name] = "ABSENT"
                continue
            recs = index.get(entity, [])
            values = []
            for rec in recs:
                val = rec.get(field)
                if val is not None:
                    val_str = str(val).strip()
                    if val_str:
                        formatted = format_date(val_str)
                        if formatted:
                            values.append(formatted)
            distinct = list(dict.fromkeys(values))
            if len(distinct) == 0:
                result[fact_name] = "ABSENT"
            elif len(distinct) == 1:
                result[fact_name] = [distinct[0], document]
            else:
                result[fact_name] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
