import json
import os
import sys

def format_date(date_str):
    """Formats a date string to YYYY-MM-DD."""
    if not date_str:
        return None
    if len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
    if len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
        return date_str
    return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Mapping based on decision rules
    # (rule_id, fact_name) -> (document_name, field_name, value_type)
    rule_mapping = {
        ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date", "date"),
        ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date", "date"),
        ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date", "date"),
        ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date", "date"),
    }

    # Load data files
    data_files = {}
    for doc_name, _, _ in set(rule_mapping.values()):
        file_path = os.path.join(packet_dir, doc_name + ".json")
