import sys
import os
import json

# Decision rules: for each rule_id, map each fact name to the document and field that establish it.
RULES = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

# The field in the record that identifies the entity (recall number)
ENTITY_FIELD = "recall_number"


def normalize_date(s: str) -> str:
    """Convert a date string to YYYY-MM-DD. Handles YYYYMMDD and already-formatted dates."""
    s = s.strip()
    if not s:
        return ""
    # YYYYMMDD
    if len(s) == 8 and s.isdigit():
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    # Already YYYY-MM-DD
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    # Fallback: return as-is (data is expected to be in one of the above formats)
    return s


def load_document(packet_dir: str, doc_name: str):
    """Load a JSON document from the packet directory. Returns a list of records."""
    # Try exact file name with .json extension
    file_path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(file_path):
        # Search for any file that starts with doc_name and has an extension
        for fname in os.listdir(packet_dir):
            if fname.startswith(doc_name + ".") or fname == doc_name:
                file_path = os.path.join(packet_dir, fname)
                break
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, dict) and "results" in data:
        return data["results"]
    if isinstance(data, list):
        return data
    # Single record object
    return [data]


def get_fact_value(packet_dir: str, doc_name: str, field: str, entity: str, doc_cache: dict):
    """Extract the value for a fact from the document, handling ABSENT and CONFLICT."""
    if doc_name not in doc_cache:
        doc_cache[doc_name] = load_document(packet_dir, doc_name)
    records = doc_cache[doc_name]

    # Find all records matching the entity
    matching = [r for r in records if str(r.get(ENTITY_FIELD, "")) == entity]
    if not matching:
        return "ABSENT"

    values = []
    for r in matching:
        val = r.get(field, "")
        if val is None:
            val = ""
        val = str(val).strip()
        val = normalize_date(val)
        values.append(val)

    unique = set(values)
    if len(unique) == 0:
        return "ABSENT"
    if len(unique) == 1:
        only = next(iter(unique))
        if only == "":
            return "ABSENT"
        return [only, doc_name]
    return "CONFLICT"


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    output = {}
    doc_cache = {}

