        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    }
}

# Mapping from document to the field that identifies the entity
DOC_ID_FIELD = {
    "fda_enforcement_reports": "recall_number"
}

def normalize_value(value, field):
    """Normalize a raw field value. Returns None for missing/empty,
    otherwise formats dates as YYYY-MM-DD."""
    if value is None:
        return None
    value = str(value).strip()
    if value == "":
        return None
    # Date fields in the FDA enforcement reports are YYYYMMDD
    if field in ("recall_initiation_date", "center_classification_date", "termination_date"):
        if len(value) == 8 and value.isdigit():
            return f"{value[:4]}-{value[4:6]}-{value[6:]}"
    return value

def get_records(data):
    """Extract a list of records from parsed JSON data."""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        if "results" in data and isinstance(data["results"], list):
            return data["results"]
        # Assume a single record dict
        return [data]
    return []

def extract_fact(packet_dir, document, field, entity):
    """Extract a fact for an entity from a document.
    Returns ["<value>", "<document>"], "ABSENT", or "CONFLICT"."""
    file_path = os.path.join(packet_dir, document + ".json")
    if not os.path.isfile(file_path):
        return "ABSENT"
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError):
        return "ABSENT"

    records = get_records(data)
    id_field = DOC_ID_FIELD.get(document, "recall_number")
    matching = [r for r in records if r.get(id_field) == entity]
    if not matching:
        return "ABSENT"

    values = []
    for r in matching:
        raw = r.get(field)
        norm = normalize_value(raw, field)
        if norm is not None:
            values.append(norm)

    if not values:
        return "ABSENT"
    unique = set(values)
    if len(unique) == 1:
        return [values[0], document]
    else:
        return "CONFLICT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    output = {}
    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
